Decision Rules
Decision rules from the Adult Decision Making Competency


Code
ts &lt;- rio::import("https://raw.githubusercontent.com/forecastingresearch/fpt/refs/heads/main/data_cognitive_tasks/task_datasets/data_time_series.csv")

session &lt;- rio::import("https://raw.githubusercontent.com/forecastingresearch/fpt/refs/heads/main/data_cognitive_tasks/metadata_tables/session.csv")

anchoraig_full &lt;- rio::import("https://raw.githubusercontent.com/forecastingresearch/fpt/refs/heads/main/data_cognitive_tasks/metadata_tables/task_aig_version.csv")




Code
anchor_ids_anchor &lt;- anchoraig_full %&gt;%
  filter(task == "time_series" & AIG_version == "anchor") %&gt;%
  pull(session_id)

ts_cl &lt;- ts |&gt;
  left_join(session,
            by = "session_id") |&gt;
  mutate(.by = c(noise_condition, datapoints, func, direction),
         ts_id = row_number()) |&gt;
  select(subject_id, ts_id, correct = mse)



Cleaning for Search Algorithm


Code
ts_dat &lt;- ts |&gt;
  left_join(session,
            by = "session_id") |&gt;
  filter(session_id %in% anchor_ids_anchor) |&gt;
  mutate(.by = c(noise_condition, datapoints, func, direction),
         ts_id = cur_group_id()) |&gt;
  left_join(rio::import("https://raw.githubusercontent.com/forecastingresearch/fpt/refs/heads/main/data_forecasting/processed_data/scores_quantile.csv") |&gt;
              select(subject_id, sscore_standardized) |&gt;

              # mean sscores per person
              summarize(.by = subject_id,
                        sscore = mean(sscore_standardized)),
            by = "subject_id") |&gt;
  select(subject_id, ts_id, score = mse, sscore, noise_condition, datapoints, func, direction)

if (!file.exists(here::here("Data", "Time Series"))) dir.create(here::here("Data", "Time Series"))
saveRDS(ts_dat, here::here("Data", "Time Series", "ts_dat.rds"))

Item Rank in Search Alg


Code
test &lt;- readRDS(here::here("Data", "Search Algorithms", "v5test_dat.rds"))
ts_dat &lt;- readRDS(here::here("Data", "Time Series", "ts_dat.rds"))

dat &lt;- ts_dat |&gt;
  mutate(item = paste0("ts_", ts_id)) |&gt;
  left_join(test |&gt;
              filter(task == "ts"),
            by = "item") |&gt;
  mutate(alg_rank = factor(rep, ordered = T))

# lm(as.numeric(alg_rank) ~ proportion_difference_scaled * small_lottery_gold_prop, dat) |&gt;
#   summary()

dat |&gt;
  select(alg_rank, noise_condition, datapoints, func, direction) |&gt;
  unique() |&gt;
  ggplot(aes(y = as.numeric(alg_rank), x = datapoints, color = direction, label = as.numeric(alg_rank))) +
  geom_point(position = position_dodge(.5), alpha = 0.3, shape = 16, size = 3) +
  geom_text(position = position_dodge(.5)) +
  facet_grid(noise_condition ~ func, axes = "all") +
  theme_classic() 









Code
list("noise_condition", "datapoints", "func", "direction") |&gt;
  map(~ lm(as.numeric(alg_rank) ~ noise_condition + datapoints + func + direction, dat) |&gt;
        ggeffects::ggpredict(terms = .x) |&gt;
        plot() +
        labs(title = NULL, x = case_when(.x == "noise_condition" ~ "Noise",
                                         .x == "datapoints" ~ "Datapoints",
                                         .x == "func" ~ "Function",
                                         .x == "direction" ~ "Direction")) +
        coord_cartesian(ylim = c(5, 15)) +
        theme_classic() +
        theme(aspect.ratio = 1)) |&gt;
  patchwork::wrap_plots(nrow = 1)











